import type { D1AuthoredBank } from '../corpus'

export const LEMBAH_AWAN_D_R8: D1AuthoredBank = {
  universeId: 'lembah-awan',
  rubricId: 'D-R8',
  STRONG: [
    { chapters: [
      { chapterNumber: 41, title: 'Bambu Melenting di Lereng', paragraphs: ['Karsa menemukan tiga bilah bambu penahan tanah melenting menjauhi lereng setelah kru Bagas menancapkan tiang berat di atas kebun kopi. Retakan tipis membelah jalan menuju sekolah. Vina memasang bilah tambahan pada jarak satu depa, lalu meminta Bu Ningsih memindahkan murid dari ruang paling dekat tebing sebelum kantor menyebut retakan itu biasa.'] },
      { chapterNumber: 42, title: 'Kelereng Bergerak Sendiri', paragraphs: ['Bu Ningsih meletakkan kelereng murid pada lantai kelas dan semuanya menggelinding ke dinding lereng. Vina mengukur pergeseran bilah dengan benang, sementara para orang tua memindahkan buku ke balai. Sekolah belum runtuh, namun lantai miring dan bambu membuktikan tanah terus bergerak. Mereka harus memilih tempat aman sebelum hujan berikutnya tiba.'] },
      { chapterNumber: 43, title: 'Cekungan di Kebun Vina', paragraphs: ['Mbah Ripto menunjukkan cekungan kosong di bawah teras Vina yang dapat menerima lumpur bila jalurnya dibuka. Jalur terpendek melewati tungku pengering kopi warisan ayahnya. Bu Ningsih menolak meminta pengorbanan itu dan mengusulkan evakuasi panjang. Vina menandai arah aliran dengan sekam, tetapi belum sanggup menjawab apa yang rela ia hilangkan.'] },
      { chapterNumber: 44, title: 'Latihan Turun Tanpa Panik', paragraphs: ['Anak-anak berlatih meninggalkan kelas melalui kebun pisang, dipandu tali yang dipasang Karsa. Dua murid kecil tersandung saat orang dewasa berteriak, sehingga Bu Ningsih mengulang latihan dalam diam memakai ketukan kaleng. Vina menyiapkan cangkul dekat tungku. Persiapan itu menyelamatkan waktu, tetapi tidak menghentikan massa tanah yang semakin menekan bilah bambu.'] },
      { chapterNumber: 45, title: 'Bagas Menarik Pekerjanya', paragraphs: ['Bagas menarik semua pekerja dari lereng dan melarang kayu kantor dipakai menyangga sekolah. Ia menawarkan truk untuk memindahkan keluarga Vina bila mereka menyerahkan cekungan kepada kebun teh. Vina menolak tawaran itu. Bu Ningsih marah karena penolakannya mempertaruhkan murid, lalu keduanya berpisah tanpa sepakat apakah sekolah atau rumah harus dikorbankan.'] },
      { chapterNumber: 46, title: 'Hujan Mematahkan Dua Bilah', paragraphs: ['Hujan malam mematahkan dua bilah dan mendorong tanah sampai pagar sekolah. Bu Ningsih menutup kelas sepenuhnya, sedangkan warga menggali parit pemecah lumpur menuju cekungan. Ujung parit berhenti di dinding teras Vina. Danu menawarkan membongkar tungku sendiri, tetapi Vina meminta semua orang menunggu sampai murid serta keluarga bawah selesai dievakuasi.'] },
      { chapterNumber: 47, title: 'Tungku Warisan Dirobohkan', paragraphs: ['Ketika derak terdengar dari punggung lereng, Vina mengayunkan palu ke tungku pengering keluarganya. Danu dan Karsa merobohkan bata lain, lalu membuka dinding teras selebar dua depa. Lumpur pertama menerobos bekas tungku menuju cekungan. Bu Ningsih membawa murid terakhir turun sambil melihat kebun kopi Vina terbelah oleh aliran cokelat.'] },
      { chapterNumber: 48, title: 'Sekolah Berdiri Tanpa Halaman', paragraphs: ['Longsor berhenti di cekungan setelah meratakan tungku, petak kopi, dan separuh halaman sekolah. Ruang kelas masih berdiri, tetapi Vina kehilangan tempat mengeringkan panen serta pohon terbaik keluarganya. Bu Ningsih meminta maaf karena sempat menjadikan pilihan itu beban Vina seorang. Mereka sepakat sekolah baru tidak boleh dibangun kembali tepat di kaki lereng.'] },
      { chapterNumber: 49, title: 'Kelas Dibuka di Balai', paragraphs: ['Pelajaran dimulai di balai dengan meja tidak seragam dan dinding tanpa jendela. Anak-anak menggambar posisi bilah bambu, bukan untuk memuji bencana, melainkan memahami mengapa tanah bergerak. Vina menjual sisa kopi basah dengan harga rendah. Bu Ningsih menyisihkan sudut kelas untuk rencana tungku bersama yang kelak dapat dipakai semua penanam.'] },
      { chapterNumber: 50, title: 'Lingkar Bata Menampung Hujan', paragraphs: ['Kecamatan melarang pemasangan tiang baru dan menetapkan cekungan sebagai ruang penahan longsor. Sekolah tetap belajar di balai sampai bangunan aman tersedia. Vina menanam kopi pada petak sempit bersama Danu, tanpa janji panen cepat. Di bekas tungku ayah mereka, lingkar bata yang tersisa menampung air hujan sementara bilah bambu baru berdiri lurus di lereng.'] },
    ], justification: 'The ending makes measured slope movement force Vina to destroy her inherited drying kiln and terrace, saving the school while leaving durable economic and spatial loss.' },
    { chapters: [
      { chapterNumber: 41, title: 'Abu Hangat di Daun', paragraphs: ['Abu hangat menempel pada daun teh yang basah meski tidak ada tungku desa menyala. Vina mengikuti serpihannya sampai batas kebun dan menemukan rumput kering sengaja dibiarkan menyambung ke lumbung. Karsa mengenali bekas sabit buatannya pada batang yang dipangkas. Keduanya menduga seseorang menyiapkan jalan api sebelum angin timur menguat.'] },
      { chapterNumber: 42, title: 'Garis Rumput Diputus', paragraphs: ['Vina mengajak keluarga lereng mencabut rumput sepanjang batas rumah, tetapi Karsa menolak memimpin. Ia mengaku pernah menjual enam sabit kepada kru Bagas tanpa menanyakan kegunaannya. Warga mulai meragukannya. Vina meminta Karsa menunjukkan cara membaca arah pangkasan, lalu membiarkan setiap keluarga memeriksa pekarangannya sendiri sebelum memutuskan apakah ia masih layak dipercaya.'] },
      { chapterNumber: 43, title: 'Sekat Pertama Terlalu Sempit', paragraphs: ['Karsa membuat sekat tanah kupas selebar dua langkah di belakang balai. Mereka membakar segenggam ilalang untuk mengujinya, namun bara terbang melewati batas dan menghanguskan pagar kosong. Vina memadamkan api bersama para ibu. Kegagalan itu memaksa Karsa mengakui bahwa angin puncak membutuhkan sekat jauh lebih lebar daripada lahan yang rela diserahkan warga.'] },
      { chapterNumber: 44, title: 'Gentong Berbaris di Punggung', paragraphs: ['Warga menaruh gentong air dan karung tanah di punggung kebun sambil memangkas ranting rendah. Bu Ningsih melatih anak-anak menuju sawah basah bila kentongan berbunyi tiga kali. Bagas menyebut persiapan itu hasutan dan melarang pekerja kebun membantu. Vina tetap membagi kelompok jaga, sedangkan Karsa menandai arah angin dengan pita daun pisang.'] },
      { chapterNumber: 45, title: 'Bengkel Dilempari Jelaga', paragraphs: ['Seseorang melempar jelaga bercampur minyak ke dinding bengkel Karsa pada malam hari. Karsa ingin pergi dari lembah sebelum kebakaran dan berkata semua orang akan menuduhnya bila api muncul. Vina tidak menghapus kesalahannya menjual sabit, tetapi meminta ia memilih apakah pengetahuan tangannya akan dipakai untuk meninggalkan warga atau menyiapkan pertahanan terakhir.'] },
      { chapterNumber: 46, title: 'Angin Membalik Pita Daun', paragraphs: ['Pita daun pisang mendadak mengarah ke rumah-rumah saat angin timur berbelok. Sekat aman kini harus melewati kebun teh Vina yang siap dipetik. Danu menolak karena panen itu membayar kebutuhan mereka sampai musim hujan. Karsa menawarkan membuat bakar-balik lebih dekat lumbung, tetapi percobaan pagar hangus membuktikan jarak tersebut tidak cukup.'] },
      { chapterNumber: 47, title: 'Api Muncul dari Puncak', paragraphs: ['Asap hitam naik dari punggung kebun ketika anak-anak telah turun ke sawah. Kelompok jaga memukul kentongan dan membasahi atap, sementara lidah api mengikuti rumput menuju lumbung. Vina berdiri di batas tanaman keluarganya dengan obor. Danu menyerahkan kendi minyak tanpa menyetujui kehilangan itu, lalu memilih membantu menjaga arah bakar-balik bersama Karsa.'] },
      { chapterNumber: 48, title: 'Kebun Sendiri Dibakar', paragraphs: ['Vina menyalakan baris teh miliknya dari sisi bawah. Karsa dan Danu menjaga api kecil bergerak melawan angin hingga bertemu kebakaran dari puncak. Seluruh pucuk siap petik menjadi batang hitam, tetapi api utama kehilangan bahan sebelum mencapai lumbung. Saat hujan abu reda, Vina tidak memiliki panen untuk dibawa pulang.'] },
      { chapterNumber: 49, title: 'Palu Menempa Cangkul Hangus', paragraphs: ['Karsa membuka bengkel dan mengumpulkan cangkul yang gagangnya terbakar untuk diperbaiki tanpa biaya. Ia mengaku di depan warga bahwa sabit buatannya membantu membuka jalur api, lalu menyerahkan nama pembelinya kepada kepala desa. Vina menyapu abu dari lantai lumbung. Kejujuran Karsa tidak mengembalikan kebunnya, tetapi membuat tanggung jawab tidak lagi ditanggung satu keluarga.'] },
      { chapterNumber: 50, title: 'Tunas Merah di Tanah Hitam', paragraphs: ['Penyelidikan desa menemukan minyak tersimpan di pondok kru Bagas, sementara lumbung tetap berdiri dan rumah lereng selamat. Vina bekerja memetik di kebun tetangga karena lahannya belum menghasilkan. Karsa menancapkan arit pada batas sekat sebagai pengingat pemeriksaan musim depan. Di antara batang teh hitam, tunas merah pertama muncul tanpa menjanjikan panen yang cepat.'] },
    ], justification: 'The ending builds toward a controlled counterfire that costs Vina her own harvest, saves the settlement, and makes Karsa answer openly for the tools he supplied.' },
    { chapters: [
      { chapterNumber: 41, title: 'Anyaman Jembatan Bergeser', paragraphs: ['Danu melihat anyaman pagar jembatan bergeser tiga ruas setelah gerobak kru Bagas melintas malam hari. Sambungan bawah retak, meski mandor memerintahkan warga tetap memakai jalur itu. Vina mengikat serat merah pada tiap silang bambu untuk membaca perubahan beban. Jembatan tersebut menjadi satu-satunya jalan antara rumah mereka dan dusun tempat Danu merawat seorang penanam sakit.'] },
      { chapterNumber: 42, title: 'Keranjang Menguji Bentang', paragraphs: ['Karsa menggantung keranjang batu pada bentang tengah, lalu Vina mencatat silang mana yang turun lebih dahulu. Uji ketiga membuat satu ikatan putus dan batu jatuh ke jurang. Danu meminta jembatan ditutup, tetapi warga seberang belum memiliki persediaan obat. Mereka sepakat membatasi lintasan sambil menyiapkan cara mengirim barang tanpa membawa tubuh melintasi retakan.'] },
      { chapterNumber: 43, title: 'Tali Meluncurkan Obat', paragraphs: ['Danu memasang tali miring dan mengirim bungkusan obat dalam keranjang kecil ke dusun seberang. Percobaan pertama tersangkut di tengah, lalu Vina menambahkan roda kayu buatan Karsa. Bungkusan berikutnya tiba utuh. Jalur sederhana itu belum mengangkut manusia, tetapi memberi mereka kemungkinan memutus jembatan tanpa meninggalkan keluarga sakit sepenuhnya terasing.'] },
      { chapterNumber: 44, title: 'Jejak Lumpur pada Bilah', paragraphs: ['Serat merah bergeser lagi setelah malam tanpa warga melintas. Lumpur pada pagar memuat sekam gudang kantor, menunjukkan gerobak Bagas masih memakai jembatan diam-diam. Vina ingin menangkap rombongan berikutnya, sedangkan Danu menolak menjadikan retakan sebagai perangkap. Mereka memasang lonceng pada pangkal dan mulai memindahkan warga seberang sebelum mencari siapa yang membawa muatan.'] },
      { chapterNumber: 45, title: 'Nenek Terakhir Menyeberang', paragraphs: ['Warga mengantar seorang nenek melewati bentang dengan tali pinggang sebelum hujan turun. Danu tetap di dusun seberang untuk menjaga penanam sakit dan berkata Vina tidak boleh memotong jembatan selagi ia di sana. Vina berjanji menunggu isyarat kain putih dari bukit. Janji itu membatasi tindakannya ketika tiap bunyi bambu menandakan keruntuhan makin dekat.'] },
      { chapterNumber: 46, title: 'Gerobak Datang Saat Hujan', paragraphs: ['Lonceng pangkal berbunyi ketika gerobak kantor membawa peti melaju dalam hujan. Vina dan warga menghadang, tetapi kru memukul kendali dan terus maju. Dua silang bambu patah di belakang roda pertama. Dari seberang, Danu mengangkat kain putih karena pasien telah aman, lalu berteriak agar kakaknya menyelamatkan orang, bukan mempertahankan bentang yang sudah gagal.'] },
      { chapterNumber: 47, title: 'Bentang Tengah Diputus', paragraphs: ['Setelah kru berlari kembali ke sisi kantor, Vina mengayunkan parang pada ikatan utama. Karsa memotong tali kedua dan bentang tengah jatuh bersama gerobak kosong ke dasar jurang. Peti tertahan di sisi atas, tetapi Danu terpisah dari rumah tanpa jalan pulang. Keputusan itu menghentikan lintasan Bagas sekaligus mengubah kehidupan kedua dusun untuk berbulan-bulan.'] },
      { chapterNumber: 48, title: 'Danu Tinggal di Seberang', paragraphs: ['Danu tidur di rumah penanam yang telah pulih dan berbicara dengan Vina melalui jurang saat udara cerah. Ia mengaku marah karena janji pulang mereka hilang bersama jembatan, meski pemotongan tadi menyelamatkan kru. Vina tidak meminta pengampunan cepat. Mereka menyusun giliran keranjang agar makanan, surat, dan obat tetap bergerak sementara bentang baru dirancang.'] },
      { chapterNumber: 49, title: 'Kabel Pertama Direntangkan', paragraphs: ['Karsa merentangkan kabel bekas pengangkut teh di antara dua pangkal, dibantu warga dari kedua sisi. Keranjang besar dapat membawa beras dan alat, tetapi belum aman untuk manusia. Danu mengirim baju kerja Vina yang tertinggal di rumahnya sebagai tanda ia masih menjaga hubungan mereka. Vina membalas dengan bibit cabai dan pesan tanpa janji tanggal kepulangan.'] },
      { chapterNumber: 50, title: 'Dua Ujung dalam Kabut', paragraphs: ['Kecamatan menyita peti kantor yang tertahan dan melarang jembatan dibuka kembali sebelum dibangun ulang. Bagas kehilangan jalur malam, namun dusun tetap terbelah. Vina memutar roda kabel saat keranjang pertama berisi hasil kebun melintas di atas jurang. Dalam kabut, dua ujung jembatan lama bergantung tanpa bertemu, sementara suara Danu terdengar dari sisi lain.'] },
    ], justification: 'The ending turns measured bridge failure into an irreversible demolition that stops Bagas while separating Vina and Danu, then shows a limited material connection rather than instant repair.' },
    { chapters: [
      { chapterNumber: 41, title: 'Katak di Sumur Sekolah', paragraphs: ['Murid-murid menemukan puluhan katak terjebak pada dasar sumur sekolah yang mendadak surut, padahal hujan baru lewat dua malam. Bu Ningsih menutup kelas karena air minum habis. Vina melihat lumpur pada dinding sumur masih basah di satu sisi dan menduga aliran bawah tanah dialihkan. Ia berjanji mencari sumbernya sebelum menerima kiriman tangki dari kantor Bagas.'] },
      { chapterNumber: 42, title: 'Polong Hanyut ke Retakan', paragraphs: ['Vina dan Bu Ningsih melepas polong dadap kering ke rembesan di atas sekolah. Sebagian tersangkut akar, tetapi tiga buah menghilang melalui retakan batu yang mengarah ke kebun teh. Mereka memasang tampah pada mulut sumur untuk menunggu polong muncul. Percobaan itu memberi keduanya jalur pencarian tanpa menjadikan dugaan Vina sebagai satu-satunya dasar.'] },
      { chapterNumber: 43, title: 'Tampah Menangkap Polong', paragraphs: ['Menjelang fajar, satu polong dadap terbaring di tampah bersama serpih cat hijau. Karsa mengenali warna tersebut sebagai pelapis pipa kebun teh yang baru dipasang. Bu Ningsih ingin segera membawa temuan ke balai, sedangkan Vina memilih menyusuri retakan lebih dulu agar mereka mengetahui letak sambungan. Perbedaan itu membuat keduanya tegang, tetapi bukti tetap mereka simpan bersama.'] },
      { chapterNumber: 44, title: 'Pipa di Bawah Pakis', paragraphs: ['Di lereng belakang kelas, Vina menemukan pipa bercat hijau tersembunyi di bawah pakis dan tersambung pada rongga batu. Ujungnya membawa air menuju rumah pembibitan milik kebun teh. Bu Ningsih memanggil para orang tua untuk melihat sambungan sebelum disentuh. Bagas menawarkan tangki gratis bila sekolah membiarkan pipa tetap tertanam, namun guru itu menolak menukar sumur dengan ketergantungan baru.'] },
      { chapterNumber: 45, title: 'Kelas Pindah ke Kebun', paragraphs: ['Bagas mengunci halaman sekolah dengan alasan pipa berada di tanah kantor. Bu Ningsih memindahkan pelajaran ke kebun kopi milik seorang wali murid, tetapi merasa keputusannya telah membuat anak-anak kehilangan tempat aman. Vina membantu mengangkut bangku tanpa menyebut pengorbanan itu sebagai kemenangan. Mereka sepakat sumur harus dipulihkan sekalipun kelas lama tidak segera dibuka kembali.'] },
      { chapterNumber: 46, title: 'Sambungan Diperlihatkan Terbuka', paragraphs: ['Para orang tua berkumpul di lereng saat Vina membuka pakis dan menunjukkan pipa, polong, serta serpih cat yang cocok. Karsa memotong satu ruas di hadapan mereka; air langsung menyembur dari rongga menuju tanah sekolah. Bagas memerintahkan kru memasangnya kembali. Bu Ningsih berdiri di depan lubang dan meminta tiap wali memilih secara terbuka antara tangki kantor atau aliran sumur.'] },
      { chapterNumber: 47, title: 'Dinding Teras Dikorbankan', paragraphs: ['Aliran yang dilepas tertahan oleh dinding teras Vina sebelum mencapai sumur. Membongkar bagian itu berarti kehilangan petak sayur keluarganya menjelang panen. Bu Ningsih meminta mereka menunggu keputusan desa, tetapi Vina memilih merobohkan dua depa tanah bersama Danu. Air menemukan cekungan lama, sementara tanaman cabai mereka hanyut bersama lumpur ke halaman sekolah.'] },
      { chapterNumber: 48, title: 'Sumur Belum Layak Minum', paragraphs: ['Air kembali menggenangi dasar sumur, namun serpih cat membuatnya belum aman diminum. Bu Ningsih menyesal telah menolak tangki karena murid masih membawa kendi dari rumah. Vina mengingatkan bahwa penolakan itu mencegah kantor memiliki alasan menutup penyelidikan. Mereka mengumpulkan pasir, ijuk, dan tempayan untuk membuat penyaring sementara sambil menunggu pemeriksaan dari kecamatan.'] },
      { chapterNumber: 49, title: 'Bangku Mengelilingi Penyaring', paragraphs: ['Kelas berlangsung di kebun kopi dengan bangku disusun mengitari tempayan penyaring. Bu Ningsih mengajari murid mencatat warna air tiap pagi, lalu mengakui kepada Vina bahwa ruang sementara itu terasa rapuh. Vina menunjukkan tunas cabai yang diselamatkan Danu dari petak hanyut. Keduanya menerima bahwa pemulihan tidak mengembalikan semua yang dikorbankan, tetapi kini dirawat oleh lebih banyak keluarga.'] },
      { chapterNumber: 50, title: 'Katak Kembali ke Bibir Sumur', paragraphs: ['Pemeriksa kecamatan menyatakan air sumur aman setelah ruas pipa dicabut seluruhnya dan penyaringan berjalan tiga pekan. Sekolah dibuka, sementara Bagas menghadapi tuntutan atas pengalihan aliran. Vina menanam kembali cabai di petak yang lebih sempit bersama Danu. Saat lonceng kelas berbunyi, seekor katak meloncat ke bibir sumur, dan Bu Ningsih membiarkannya tinggal di antara kendi murid.'] },
    ], justification: 'The ending traces a diverted underground flow through seed pods, makes Vina sacrifice her own terrace to restore it, and resolves the school-water conflict while preserving material loss and shared care.' },
    { chapters: [
      { chapterNumber: 41, title: 'Hujan Es Merobek Atap', paragraphs: ['Hujan es merobek tiga atap bambu dan melukai seorang penanam yang berlari mencari perlindungan. Ramalan radio menyebut badai kedua akan tiba dalam sembilan hari. Bagas mengunci bangunan kantor, sementara lumbung keluarga Vina menjadi satu-satunya ruang dengan balok utuh. Vina membuka pintunya, tetapi lantai sempit tidak mungkin menampung seluruh warga lereng.'] },
      { chapterNumber: 42, title: 'Keranjang Menguji Balok', paragraphs: ['Pada setiap balok, Karsa menggantung bakul berisi batu untuk menguji beban. Satu sambungan berderit sebelum berat setara empat orang tercapai. Mbah Ripto menghitung warga yang sulit berjalan, sedangkan Vina mengukur ruang di antara rak keluarga. Agar lumbung aman, rak penyimpanan harus dibongkar dan kayunya dijadikan penyangga, mengakhiri fungsi yang diwariskan ayahnya.'] },
      { chapterNumber: 43, title: 'Mbah Menolak Tempat Dalam', paragraphs: ['Mbah Ripto menolak tempat dekat pintu karena seorang ibu dengan bayi lebih membutuhkannya. Vina menyusun urutan masuk berdasarkan kemampuan bergerak, bukan kegunaan seseorang saat bekerja. Lelaki tua itu menuduhnya mengasihani usia. Pertengkaran mereka membuat jelas bahwa perlindungan bersama akan gagal bila warga merasa keselamatan harus dibayar dengan menyerahkan martabat.'] },
      { chapterNumber: 44, title: 'Pintu Darurat Dicoba', paragraphs: ['Karsa membuka pintu darurat pada dinding belakang dan warga mencoba keluar tanpa membawa barang. Rak-rak membuat dua jalur menyempit, sementara peti keluarga Vina menghalangi belokan terakhir. Danu meminta peti itu dipindahkan. Vina menolak karena isinya pakaian ibu mereka, lalu menyadari ia sedang mempertahankan kenangan dengan ruang yang mungkin dibutuhkan tubuh hidup.'] },
      { chapterNumber: 45, title: 'Gudang Kantor Tetap Dikunci', paragraphs: ['Para ibu meminta Bagas membuka gudang teh sebagai tempat kedua, tetapi ia menuntut surat pelepasan tuntutan air. Mereka pulang tanpa kesepakatan. Vina menawarkan lumbung lagi, kali ini dengan syarat setiap keluarga hanya membawa satu bungkusan. Mbah Ripto bersedia membantu latihan masuk bila ia boleh memilih sendiri tempat duduk dan tugasnya selama badai.'] },
      { chapterNumber: 46, title: 'Latihan Pertama Gagal', paragraphs: ['Latihan masuk berubah kacau ketika anak-anak mencari orang tua dan warga berebut sudut kering. Mbah Ripto memukul lesung dengan pola berbeda untuk tiap kelompok, membuat arus manusia terpisah tanpa teriakan. Uji ulang selesai lebih cepat, namun rak timur bergoyang saat semua orang duduk. Karsa berkata penyangga tambahan tidak dapat dipasang tanpa menggergaji dudukan permanennya.'] },
      { chapterNumber: 47, title: 'Peti Ibu Dibuka', paragraphs: ['Vina membuka peti ibu bersama Danu dan membagi pakaian di dalamnya kepada keluarga yang atapnya rusak. Mereka menyimpan satu selendang, lalu memakai papan peti untuk memperkuat pintu darurat. Tindakan itu membebaskan ruang, tetapi balok utama masih membutuhkan kayu rak. Di luar, awan es menutup puncak sehari lebih cepat dari ramalan radio.'] },
      { chapterNumber: 48, title: 'Rak Warisan Digergaji', paragraphs: ['Vina menggergaji dudukan rak yang menyatu dengan dinding lumbung. Karsa memasang kayunya sebagai penyangga silang, sementara Mbah Ripto mengatur warga masuk menurut bunyi lesung. Badai menghantam sebelum papan terakhir terpasang. Semua orang berlindung, tetapi karung keluarga Vina yang tak lagi memiliki rak basah ketika air merembes sepanjang lantai.'] },
      { chapterNumber: 49, title: 'Caping pada Bekas Rak', paragraphs: ['Pagi sesudah badai, rumah-rumah masih berdiri meski banyak atap berlubang. Warga menggantung caping pada bekas rak dan membagi bahan makanan yang selamat. Mbah Ripto memilih tetap dekat pintu untuk menyambut keluarga terakhir, bukan karena diperintah Vina. Lumbung tidak dapat kembali menjadi gudang privat, dan hasil panen kini harus disimpan tersebar di beberapa rumah.'] },
      { chapterNumber: 50, title: 'Cahaya Masuk dari Dinding', paragraphs: ['Desa menetapkan lumbung sebagai tempat berlindung tetap dan membangun rak kecil pada rumah-rumah untuk mengganti penyimpanan lama. Bagas belum membuka gudang kantor, sehingga tuntutan terhadapnya berlanjut. Vina menjemur karung basah bersama Danu. Cahaya pagi masuk melalui celah dudukan papan keluarga, menerangi caping berbagai ukuran yang tertinggal setelah warga pulang.'] },
    ], justification: 'The ending forces Vina to dismantle her inherited private storehouse so it can shelter the village, while Mbah Ripto retains agency and storage loss remains unresolved.' },
  ],
  WEAK: [
    { chapters: [
      { chapterNumber: 41, title: 'Gerbang Tertutup Pagi', paragraphs: ['Bagas mengunci gerbang atas, sedangkan Vina hanya memandang teras bawah yang mengering. Ia menenteng kartu jatahnya menuju pos penjagaan, lalu pulang ketika kru menghalangi pintu. Mbah Ripto menyebut parit lama, namun Vina tidak menanyakan jalurnya. Kekeringan hanya menjadi alasan bagi kecemasan yang dibawa pulang ke dapur.'] },
      { chapterNumber: 42, title: 'Gerbang Tertutup Siang', paragraphs: ['Pada siang hari gerbang atas tetap tertutup dan tanah teras Vina makin retak. Ia mendatangi rumah jaga dengan kartu yang sama, kemudian pergi setelah kru menyuruhnya menunggu. Mbah Ripto kembali menyebut parit lama, tetapi Vina tidak meminta penjelasan. Kecemasan itu berputar tanpa mengajak seorang warga pun bertindak.'] },
      { chapterNumber: 43, title: 'Gerbang Tertutup Sore', paragraphs: ['Sore berikutnya gerbang atas masih terkunci sementara Vina melihat daun padi mulai menggulung. Ia membawa kartu ke jalan kantor, lalu berbalik sebelum bertemu mandor. Mbah Ripto menyampaikan lagi tentang jalur lama, namun tidak ada yang mencari batu penanda. Kekeringan tetap menjadi keluhan tanpa pilihan baru bagi siapa pun.'] },
      { chapterNumber: 44, title: 'Gerbang Tertutup Malam', paragraphs: ['Menjelang malam, Vina memeriksa gerbang atas yang masih terkunci dan kembali menghitung retakan tanah. Kartu jatah disimpan di saku tanpa diperlihatkan kepada warga. Mbah Ripto duduk dekat parit, tetapi Vina melewatinya. Tidak ada jalur dibersihkan, catatan dibuat, atau hubungan baru yang mengubah hari itu.'] },
      { chapterNumber: 45, title: 'Gerbang Tertutup Lagi', paragraphs: ['Ketika gerbang atas tetap tertutup, Danu berkata pekerjaan kebun teh juga sedang sepi. Vina hanya mengangguk dan memandangi ember kosong. Ia tidak menanyakan parit lama atau meminta bantuan tetangga. Kekeringan masuk ke rumah sebagai suasana muram, tanpa menuntut satu langkah pun yang berlainan dengan kemarin.'] },
      { chapterNumber: 46, title: 'Gerbang Tertutup Terus', paragraphs: ['Di balai, Bagas membacakan jadwal air lama sementara Vina berdiri di belakang warga. Ia tidak membawa bukti, daftar, atau usul jalur lain. Setelah rapat, setiap orang pulang dengan ember kosong. Penutupan gerbang belum menghasilkan tindakan bersama, sehingga kata-kata Bagas tetap menjadi satu-satunya urutan yang dipakai lembah.'] },
      { chapterNumber: 47, title: 'Hujan Lewat Sebentar', paragraphs: ['Hujan pendek membasahi pematang, lalu berhenti sebelum parit terisi. Vina melihat lumpur mengeras kembali lalu menyisipkan kartunya ke kolong alas piring. Danu tidak bertanya dan Mbah Ripto tidak datang. Cuaca berubah sedikit, tetapi sengketa air dan rumah mereka tetap tanpa tujuan yang segar.'] },
      { chapterNumber: 48, title: 'Serambi Tetap Sunyi', paragraphs: ['Keranjang kosong tergeletak di samping Danu pada lantai serambi, sedangkan Vina membawa ember dari pos penjagaan. Mereka membicarakan harga beras lalu berhenti sebelum menyebut gerbang atas. Tidak ada permintaan maaf atau rencana mencari pekerjaan lain. Kesunyian keluarga menyamai parit yang tidak bergerak di bawah bukit.'] },
      { chapterNumber: 49, title: 'Papan Lama Masih Tergantung', paragraphs: ['Papan jadwal lama masih tergantung dekat pintu air dan catnya mulai mengelupas. Vina membacanya seorang diri tanpa memberi tanda pada jam yang dipotong. Anak-anak bermain di tanah dekat parit, tetapi tidak ada yang diajak melihatnya. Lembah tetap menunggu keputusan kantor seperti pada hari-hari sebelumnya.'] },
      { chapterNumber: 50, title: 'Teras Bawah Menunggu', paragraphs: ['Pagi tanam berlalu ketika teras bawah belum mendapat air. Vina memegang bibit padi sampai akarnya mengering, lalu membawanya pulang. Bagas masih mengawasi dari bukit dan warga tidak berkumpul. Cerita berhenti pada kekurangan yang sama, tanpa cara baru untuk menghadapi musim berikutnya.'] },
    ], justification: 'All ending chapters restate water scarcity and family worry without an accumulating response, changed relationship, or future runway.' },
    { chapters: [
      { chapterNumber: 41, title: 'Karung Dibiarkan Tertutup', paragraphs: ['Bau asam menyentuh hidung Vina begitu lumbung terbuka, tetapi ia menutup pintu sebelum mengambil satu butir pun. Bagas belum tiba dan Karsa sedang bekerja di bengkelnya. Ia memilih pulang karena takut dituduh merusak jahitan. Curiga itu tinggal sebagai bau pada pakaian tanpa memberi warga kesempatan melihat apa yang ia lihat.'] },
      { chapterNumber: 42, title: 'Rak Dibiarkan Berdebu', paragraphs: ['Keesokan pagi Vina melihat serbuk kelabu di bawah rak benih. Ia menyapunya ke sudut lalu mengunci lumbung agar tidak ada yang bertanya. Karsa lewat membawa cangkul, namun tidak dipanggil. Tindakan kecil itu merapikan lantai, bukan membuka jalan untuk memahami mengapa benih mulai berubah.'] },
      { chapterNumber: 43, title: 'Bagas Membawa Karung', paragraphs: ['Bagas memindahkan dua karung ke gerobak dan berkata benih itu masih baik. Vina melihat jahitan berbeda, tetapi membiarkan nomor rak serta arah gerobak lewat tanpa dicatat. Ia membiarkan roda menghilang di tikungan. Kecurigaan tentang lumbung menjadi semakin besar, namun tidak ada bukti atau saksi yang dapat kembali memeriksanya.'] },
      { chapterNumber: 44, title: 'Tampah Kosong di Kelas', paragraphs: ['Bu Ningsih menyediakan tampah di kelas jika Vina ingin membawa contoh benih. Vina hanya menaruh sapu di sudut dan berkata ia belum yakin. Anak-anak pulang tanpa melihat apa pun. Ruang kelas kembali kosong, sementara keputusan untuk menunggu membuat kerusakan tetap tersembunyi di lumbung.'] },
      { chapterNumber: 45, title: 'Karsa Menutup Bengkel', paragraphs: ['Pintu bengkel Karsa rusak oleh angin malam, dan ia memilih menutupnya untuk memperbaiki kayu sendiri. Vina ingin mengatakan bahwa lumbung juga bermasalah, tetapi takut menambah beban sahabatnya. Ia pergi tanpa bicara. Dua persoalan tumbuh terpisah, tidak saling memberi bantuan maupun arah.'] },
      { chapterNumber: 46, title: 'Rapat Tanpa Benih', paragraphs: ['Di balai, Bagas menyebut pembagian benih akan berjalan seperti biasa. Vina berdiri dengan tangan kosong karena tidak pernah membawa contoh atau catatan rak. Warga mengangguk lalu pulang. Lumbung tetap tertutup bagi pemeriksaan, dan kata-kata mandor terus menentukan siapa mendapat karung terlebih dahulu.'] },
      { chapterNumber: 47, title: 'Bibit Tidak Berkecambah', paragraphs: ['Beberapa bibit di teras Vina gagal berkecambah, tetapi ia tidak tahu berasal dari rak mana. Danu menyarankan membeli benih baru bila ada uang. Vina menatap tanah kosong sepanjang sore. Kegagalan itu menambah kesedihan, tanpa menghubungkan keadaan teras pada lumbung atau keputusan Bagas.'] },
      { chapterNumber: 48, title: 'Danu Membawa Nasi', paragraphs: ['Danu membawa nasi bungkus dari kebun teh dan menemukan Vina memegang butir yang tidak tumbuh. Ia berkata musim memang buruk, lalu makan di serambi. Vina tidak menjelaskan bau gudang atau jahitan yang berbeda. Kehadiran kakaknya memberi teman makan, tetapi tidak menggeser kesunyian mengenai masalah mereka.'] },
      { chapterNumber: 49, title: 'Lumbung Dikunci Senja', paragraphs: ['Saat senja, Vina mengunci lumbung dan menyimpan kuncinya di tempat biasa. Karung-karung tetap tak diperiksa, sedangkan bau masam semakin terasa di sela papan. Karsa belum tahu, Bu Ningsih tidak memiliki daftar, dan warga pulang. Tidak ada pengetahuan bersama yang dapat menahan kerusakan sebelum musim berikutnya.'] },
      { chapterNumber: 50, title: 'Karung Baru Tetap Sama', paragraphs: ['Pagi berikutnya kantor mengirim karung baru tanpa menjelaskan asalnya. Vina menaruhnya di rak dan mencoba tidak mencium baunya. Bagas mengawasi dari pintu, sementara warga menunggu pembagian. Cerita berakhir dengan lumbung yang masih dikuasai ketakutan dan benih yang tidak pernah benar-benar diperiksa.'] },
    ], justification: 'The contaminated-seed thread gathers suggestive details but Vina never turns them into shared evidence or a changed ending.' },
    { chapters: [
      { chapterNumber: 41, title: 'Surat Danu Basah', paragraphs: ['Danu membawa surat peringatan dari kebun teh setelah terlambat menjaga lumbung. Hujan membuat sudut surat basah dan ia menyalahkan Vina karena meminta bantuannya. Vina menyuruhnya tidur, bukan mendengarkan rasa takutnya. Mereka menutup percakapan dengan marah, sementara pekerjaan Danu tetap berada di ujung keputusan orang lain.'] },
      { chapterNumber: 42, title: 'Keranjang Ditumpuk di Dapur', paragraphs: ['Danu menaruh keranjang teh di dapur dan berangkat sebelum Vina bangun. Ia tidak membuka surat peringatan lagi. Vina melihatnya dari pintu, tetapi hanya menanak nasi untuk dirinya sendiri. Jarak mereka menjadi kebiasaan rumah, tanpa percakapan yang menghubungkan kerja Danu dengan perjuangan air warga.'] },
      { chapterNumber: 43, title: 'Mandor Kebun Memanggil', paragraphs: ['Mandor kebun teh memanggil Danu untuk kerja tambahan pada hari rapat warga. Danu pergi tanpa berkata apakah ia akan hadir di balai. Vina membiarkannya karena takut permintaan apa pun akan menjadi beban. Pilihan Danu terasa berat, tetapi tidak menghasilkan cara baru bagi kakak beradik itu untuk saling mendukung.'] },
      { chapterNumber: 44, title: 'Piring Dibiarkan Dingin', paragraphs: ['Malam rapat, nasi Danu dibiarkan dingin di atas piring. Vina menyelipkan kartu jatahnya ke sela alas meja dan tidak pergi mencarinya. Danu pulang terlambat lalu langsung tidur. Rumah menahan dua ketakutan yang tidak pernah saling disebut, sehingga masalah pekerjaan dan air bergerak tanpa bantuan keluarga.'] },
      { chapterNumber: 45, title: 'Danu Kehilangan Giliran', paragraphs: ['Kebun teh mengurangi hari kerja Danu karena ia tidak mau menjaga saluran pada malam tertentu. Ia membanting keranjang ke dinding dan berkata semua ini dimulai dari Vina. Vina menangis di dekat tungku, tetapi tidak menjawab. Kemarahan mereka menjadi tujuan akhir pertengkaran, bukan pintu menuju pengakuan atau pemulihan.'] },
      { chapterNumber: 46, title: 'Balai Terasa Jauh', paragraphs: ['Warga menyusun jadwal air baru di balai, sementara Danu tetap bekerja di kebun teh. Vina tidak membaca hasil rapat kepadanya saat pulang. Danu tidak bertanya. Keputusan desa berjalan terpisah dari keluarga yang paling menanggung risikonya, dan tidak ada jembatan emosional dibangun di antara keduanya.'] },
      { chapterNumber: 47, title: 'Upah Dipotong Lagi', paragraphs: ['Upah Danu dipotong karena ia pulang untuk memeriksa atap rumah yang bocor. Ia menyimpan uang receh di kaleng dan menolak makan malam. Vina ingin membantu, tetapi hanya meletakkan selimut di dekatnya. Perhatian diam itu tidak memberi mereka bahasa untuk membahas kehilangan yang terus bertambah.'] },
      { chapterNumber: 48, title: 'Serambi Tanpa Rencana', paragraphs: ['Danu bersandar di tiang serambi bersama keranjang kosongnya, dan Vina membawa air minum tanpa menanyakan pekerjaannya. Mereka mendengar jangkrik sampai malam. Tidak ada daftar kebun lain, permintaan maaf, atau kesediaan untuk menghadapi masa depan bersama. Kedekatan ruang tidak mengurangi jarak yang telah tumbuh di antara mereka.'] },
      { chapterNumber: 49, title: 'Surat Masuk Peti', paragraphs: ['Vina menemukan surat kerja Danu lalu memasukkannya ke peti agar tidak sobek. Danu melihatnya dan hanya berkata biarkan saja. Mereka tidak membicarakan pekerjaan, kebun teh, atau alasan Vina membawa warga ke balai. Surat tersimpan rapi, sementara luka mereka tetap tanpa nama dan tanpa jalan pulang.'] },
      { chapterNumber: 50, title: 'Danu Berangkat Sendiri', paragraphs: ['Saat fajar, Danu pergi mencari kerja harian tanpa memberi tahu tujuan. Vina menanam padi seorang diri di teras bawah. Air mengalir sedikit, tetapi rumah mereka tidak memiliki rencana yang sama. Cerita selesai dengan dua saudara yang masih berjalan ke arah berbeda, sehingga keberhasilan warga tidak menyentuh pusat keluarga mereka.'] },
    ], justification: 'The public conflict advances around Danu, but the ending leaves Vina and her brother emotionally and practically disconnected.' },
    { chapters: [
      { chapterNumber: 41, title: 'Peta Tidak Dibuka', paragraphs: ['Mbah Ripto membawa peta parit lama ke rumah jaga ketika gerbang atas ditutup. Vina berkata jalur itu pasti sudah hilang lalu menyimpan gulungan di peti. Warga menunggu di dekat ember kosong sampai senja. Tidak ada yang melihat tanda arah atau mencoba menemukan belokan yang dulu mengaliri teras bawah.'] },
      { chapterNumber: 42, title: 'Batu Tertutup Semak', paragraphs: ['Dari jalan kebun kopi, Vina melihat semak tinggi di tempat batu putih seharusnya berada. Ia tidak mendekat karena merasa jalur lama bukan urusannya. Danu lewat membawa keranjang dan tidak diajak berhenti. Semak itu tetap menutup kemungkinan lain, sementara warga kembali menunggu pintu air yang dijaga kru Bagas.'] },
      { chapterNumber: 43, title: 'Kru Menjaga Pintu Air', paragraphs: ['Kru Bagas memasang papan larangan dekat saluran lama dan berkata siapa pun yang melintas akan didenda. Vina membaca tulisan itu lalu pulang. Mbah Ripto tidak diberi kesempatan menjelaskan sejarah jalur tersebut. Ancaman kantor diterima sebagai akhir pembicaraan, sehingga pilihan warga menyempit tanpa pernah diuji.'] },
      { chapterNumber: 44, title: 'Ember Berbaris di Halaman', paragraphs: ['Ember kosong berbaris di halaman rumah jaga, tetapi Vina tidak membuat daftar pemiliknya. Bu Ningsih menawarkan kapur, lalu Vina berkata catatan tidak akan mengubah apa pun. Para ibu membawa wadah kembali ketika malam turun. Kekurangan air menjadi pemandangan bersama tanpa membuat siapa pun tahu keluarga mana yang paling terdampak.'] },
      { chapterNumber: 45, title: 'Danu Menjaga Jarak', paragraphs: ['Danu memilih mengambil giliran kerja tambahan di kebun teh dan tidak datang saat warga membahas air. Vina merasa kakaknya meninggalkannya, tetapi tidak menanyakan mengapa ia takut kehilangan upah. Mereka melewati makan malam tanpa bicara. Rumah menambah kesunyian pada masalah yang sudah membuat warga saling menunggu.'] },
      { chapterNumber: 46, title: 'Rapat Berakhir Cepat', paragraphs: ['Bagas datang ke balai dengan jadwal kantor dan tidak ada warga membawa peta, daftar ember, maupun penanda parit. Ia membacakan jam lama lalu menutup rapat. Vina menyaksikan orang-orang pulang sebelum pertanyaan muncul. Tanpa bahan untuk menantang urutan itu, pertemuan hanya mengulang kuasa yang sudah mereka keluhkan.'] },
      { chapterNumber: 47, title: 'Tanah Retak Kembali', paragraphs: ['Angin panas mengeringkan tanah setelah hujan singkat. Vina memeriksa retakan di teras, lalu membuang bibit yang tidak dapat ditanam. Tidak ada warga datang berbagi air atau mencari jalur lain. Kerusakan musim diperlakukan sebagai nasib, sehingga setiap keluarga tetap menghadapi terasnya sendiri-sendiri.'] },
      { chapterNumber: 48, title: 'Mbah Ripto Menutup Peta', paragraphs: ['Mbah Ripto membuka peta sekali lagi di teras rumahnya, tetapi Vina hanya melihatnya dari jalan. Lelaki tua itu menggulung kertas ketika tidak ada yang berhenti. Ia tidak menceritakan nama belokan atau pintu kayu kepada anak-anak. Ingatan tentang jalur lama kembali masuk peti bersama kesempatan untuk memakainya.'] },
      { chapterNumber: 49, title: 'Parit Lama Tetap Diam', paragraphs: ['Rumput tumbuh pada parit lama dan air tipis mengalir ke arah yang tidak diketahui. Vina berdiri di dekatnya tanpa membawa alat atau teman. Dari bukit, bunyi peluit kru Bagas memanggil penjaga gerbang. Tidak ada tindakan yang mengubah hubungan lembah dengan air, dan rasa takut tetap menentukan jarak setiap orang.'] },
      { chapterNumber: 50, title: 'Musim Lewat Tanpa Jalur', paragraphs: ['Pada akhir musim, teras bawah hanya menumbuhkan beberapa rumpun padi pendek. Vina menyimpan peta lama di bawah tempat tidur, sementara Bagas tetap memegang jadwal kantor. Warga tidak memiliki catatan atau jalur bersama untuk dicoba. Cerita menutup musim tanpa memberi lembah pegangan yang dapat dibawa menuju tahun berikutnya.'] },
    ], justification: 'A possible collective water route is repeatedly ignored, leaving scarcity and office control unchanged through the final chapter.' },
    { chapters: [
      { chapterNumber: 41, title: 'Kunci Tetap di Sabuk', paragraphs: ['Bagas berjalan melewati lumbung dengan kunci di sabuknya saat Vina melihat sepasang goni diangkut tanpa dicatat siapa pun. Ia ingin menanyakan tujuan karung itu, tetapi memilih menyusun rak yang tersisa. Karsa sedang menajamkan sabit di halaman dan tidak diberi tahu. Penguasaan sendirian atas daun pintu gudang tidak pernah digugat.'] },
      { chapterNumber: 42, title: 'Jahitan Tidak Diperiksa', paragraphs: ['Vina melihat jahitan karung berubah dari benang merah menjadi tali kasar. Ia menutupinya dengan debu agar Bagas tidak melihat bahwa ia curiga. Tidak ada nomor rak ditulis atau potongan benang disimpan. Perubahan kecil itu hilang dari ingatan begitu pintu lumbung ditutup kembali.'] },
      { chapterNumber: 43, title: 'Gerobak Lewat Jalan Bawah', paragraphs: ['Sebuah gerobak keluar melalui jalan bawah sebelum fajar. Vina mendengar roda menggesek batu, tetapi tidak melihat isinya karena takut mengikuti. Ketika matahari naik, rak lumbung sudah tampak berbeda. Tidak ada tanda fisik yang dapat menghubungkan gerobak itu dengan karung tertentu atau dengan Bagas.'] },
      { chapterNumber: 44, title: 'Karsa Tidak Dihubungi', paragraphs: ['Bu Ningsih bertanya apakah lumbung perlu kunci tambahan, lalu Vina menjawab Bagas pasti tidak mengizinkannya. Karsa tidak pernah diminta menilai bentuk kunci atau membuat kotak bersama. Gagasan penjagaan bersama berhenti di kalimat pendek. Pintu gudang tetap menjadi batas yang tidak dapat dilewati warga.'] },
      { chapterNumber: 45, title: 'Bagas Mengambil Daftar', paragraphs: ['Bagas mengambil buku penerimaan dari meja lumbung dan membawanya ke kantor. Vina melihat halaman terakhir belum selesai ditulis, tetapi tidak membuat salinan. Ia pulang dengan tangan kosong. Danu menanyakan mengapa ia pucat, lalu Vina menjawab lelah. Kehilangan catatan tidak menggerakkan mereka untuk menyusun bukti baru.'] },
      { chapterNumber: 46, title: 'Lumbung Dibuka Sebentar', paragraphs: ['Pada rapat, Bagas membuka lumbung sebentar lalu menunjuk rak yang menurutnya penuh. Vina tidak dapat menyebut jumlah semula atau nama penerima karung sebelumnya. Warga melihat tumpukan goni dari kejauhan dan percaya pada hitungan mandor. Tidak ada penjaga lain atau papan catatan yang mengubah pemeriksaan tersebut.'] },
      { chapterNumber: 47, title: 'Rak Kosong Menjelang Hujan', paragraphs: ['Hujan membuat lumbung bocor dan satu rak tampak lebih kosong dari biasanya. Vina menaruh ember di bawah tetesan, bukan mencatat karung yang hilang. Karsa lewat membawa payung, tetapi tidak diajak masuk. Kerusakan air dan hilangnya benih tetap menjadi dua masalah yang tidak pernah dipertemukan.'] },
      { chapterNumber: 48, title: 'Danu Meminta Diam', paragraphs: ['Danu meminta Vina berhenti membicarakan lumbung karena kontraknya di kebun teh belum aman. Vina menyimpan kunci biasa di atas rak dan berkata tidak apa-apa. Mereka makan tanpa membahas karung yang terus keluar. Hubungan keluarga menambah alasan untuk diam, bukan tempat untuk menyusun keberanian bersama.'] },
      { chapterNumber: 49, title: 'Pintu Gudang Masih Sama', paragraphs: ['Pintu lumbung tetap berengsel retak dan kunci tunggal masih bergantung pada sabuk Bagas. Vina menyapu halaman tanpa memanggil Bu Ningsih atau Karsa. Karung baru datang, sedangkan asal karung lama tidak pernah diketahui. Warga tetap bergantung pada pintu yang tidak mereka jaga maupun pahami.'] },
      { chapterNumber: 50, title: 'Benih Dibagi Tanpa Catatan', paragraphs: ['Pada pagi pembagian, Bagas menyebut nama penerima dari buku kantor dan warga menerima karung tanpa tanda terima. Vina melihat dua keluarga pulang dengan tangan kosong, tetapi tidak dapat menjelaskan mengapa. Lumbung masih tertutup bagi pengawasan bersama. Cerita berakhir dengan benih sebagai alat kuasa yang tidak pernah berhasil disentuh warga.'] },
    ], justification: 'The storehouse-control thread creates repeated suspicious signs but no shared custody, record, or satisfying answer.' },
  ],
  BORDERLINE: [
    { chapters: [
      { chapterNumber: 41, title: 'Kartu Jatah Disimpan', paragraphs: ['Vina menyimpan kartu jatah yang dipotong di bawah alas piring setelah Bagas menolak pertanyaannya. Ia tidak membuat salinan, tetapi Bu Ningsih sempat melihat tinta biru pada angka. Petunjuk kecil itu belum mengubah pembagian air, namun memberi Vina seseorang yang mengetahui keluhannya bukan sekadar perasaan sendiri.'] },
      { chapterNumber: 42, title: 'Satu Angka Dicatat', paragraphs: ['Di pasar, Vina menyalin satu jam dari kartu tetangga pada telapak tangannya. Ia tidak tahu apakah pemotongan itu bagian dari pola atau kesalahan biasa. Bu Ningsih meminta ia menyimpan catatan itu, tetapi belum mengajak warga lain. Informasi baru muncul, meski terlalu kecil untuk mengubah keputusan Bagas.'] },
      { chapterNumber: 43, title: 'Bagas Mengulang Jawaban', paragraphs: ['Bagas berkata jadwal sudah final ketika Vina kembali membawa kartunya. Vina tidak menyerahkan catatan telapak tangan atau menyebut kartu tetangga. Ia pulang dengan marah, sementara Bu Ningsih belum melihat papan jadwal secara langsung. Perlawanan mulai memiliki jejak, tetapi masih tidak menemukan tempat terbuka untuk tumbuh.'] },
      { chapterNumber: 44, title: 'Kapur Disimpan di Kelas', paragraphs: ['Bu Ningsih menyimpan kapur dan dua kartu jatah di laci kelas untuk dibandingkan nanti. Vina merasa sedikit lega karena bukti tidak hanya berada di rumahnya. Namun rapat warga ditunda akibat hujan, dan tidak ada daftar lengkap dibuat. Persiapan memberi arah, tetapi sengketa air masih berjalan memakai urutan kantor.'] },
      { chapterNumber: 45, title: 'Danu Menolak Rapat', paragraphs: ['Danu meminta Vina tidak menghadiri rapat warga karena kebun teh sedang menilai kontraknya. Vina tidak pergi, tetapi ia juga tidak membuang kartu yang disimpan Bu Ningsih. Keputusan itu menjaga hubungan rumah dari pertengkaran besar, sambil membiarkan pemotongan air belum ditantang secara nyata.'] },
      { chapterNumber: 46, title: 'Kartu Dibaca Dua Ibu', paragraphs: ['Dua ibu memeriksa kartu jatah masing-masing di kelas bersama Vina dan menemukan jam mereka berbeda dari papan gerbang. Mereka setuju membawa kartu lain bila ada kesempatan. Bagas tidak mengetahui pertemuan itu. Kemajuan tersebut membangun kemungkinan kelompok kecil, tetapi belum cukup mengubah jadwal atau perlindungan bagi teras bawah.'] },
      { chapterNumber: 47, title: 'Hujan Menutup Jalan', paragraphs: ['Hujan deras menutup jalan menuju balai dan membuat pertemuan kartu dibatalkan. Vina membantu ibu-ibu menyelamatkan ember, lalu menyimpan salinan di kaleng teh. Kepedulian itu memperkuat hubungan mereka, tetapi bukti masih tidak sampai ke tempat yang dapat menahan keputusan Bagas.'] },
      { chapterNumber: 48, title: 'Danu Melihat Salinan', paragraphs: ['Danu menemukan salinan kartu di kaleng teh dan membaca angka yang dipotong. Ia tidak lagi menyebut Vina berlebihan, tetapi meminta waktu sebelum ikut rapat. Vina mengangguk. Pengakuan kecil itu mengendurkan ketegangan keluarga, walau mereka belum memiliki rencana bersama menghadapi kantor.'] },
      { chapterNumber: 49, title: 'Papan Masih Tanpa Tanda', paragraphs: ['Papan jadwal tetap tergantung di gerbang tanpa koreksi, meski Vina kini menyimpan beberapa kartu pembanding. Bu Ningsih menyarankan membawa semuanya setelah musim hujan reda. Vina menunggu sambil menjaga kaleng teh. Harapan memperoleh bukti bersama ada, namun belum memberi warga kendali atas air hari ini.'] },
      { chapterNumber: 50, title: 'Bibit Menunggu Air', paragraphs: ['Pada pagi tanam, Vina menunda sebagian bibit karena jatah air belum berubah. Danu membantu menutup kaleng berisi salinan kartu sebelum berangkat kerja. Mereka sepakat memeriksa kartu lain minggu depan. Cerita memberi mereka hubungan dan arah awal, tetapi penyelesaian pemotongan serta masa depan teras masih tertunda.'] },
    ], justification: 'The cards create a modest evidence network and soften family tension, but no public challenge or water-governance change arrives by the ending.' },
    { chapters: [
      { chapterNumber: 41, title: 'Satu Benang Merah', paragraphs: ['Vina mengikat benang merah pada satu karung benih ketika lumbung mulai terasa aneh. Nomor rak dan jumlah butir dibiarkan tanpa catatan karena takut Bagas melihat. Karsa memperhatikan simpul itu dari halaman, namun tidak bertanya. Tanda kecil memberi Vina perhatian baru, tanpa membuat pengawasan lumbung menjadi milik warga.'] },
      { chapterNumber: 42, title: 'Simpul Tetap Utuh', paragraphs: ['Karung bertanda masih utuh, tetapi dua goni lain bergeser ke dekat pintu. Vina menunjukkan perbedaan itu kepada Karsa secara singkat. Tukang besi menyarankan memberi tanda lain, namun ia belum punya bahan atau keberanian. Temuan tersebut menguatkan curiga, tetapi tidak dapat menjelaskan apa yang terjadi pada rak lain.'] },
      { chapterNumber: 43, title: 'Gerobak Meninggalkan Jejak', paragraphs: ['Gerobak kantor meninggalkan bekas roda di halaman setelah membawa satu karung keluar. Vina melihatnya bersama Karsa, tetapi mereka tidak tahu rak asal goni itu. Bagas menyebutnya pengiriman biasa. Jejak roda dan simpul merah memberi dua potong keadaan, namun belum menyatu menjadi bukti yang dapat dibawa ke balai.'] },
      { chapterNumber: 44, title: 'Karsa Membawa Lilin', paragraphs: ['Karsa membawa lilin bekas dan berkata mungkin kunci lumbung dapat disalin bila Vina berani melihat bentuknya. Vina menyimpan lilin di bawah papan lantai, tetapi belum mendapat kesempatan mendekati meja Bagas. Gagasan penjagaan bersama mulai ada, meski pintu gudang tetap hanya dibuka oleh mandor.'] },
      { chapterNumber: 45, title: 'Bagas Mengambil Buku', paragraphs: ['Bagas membawa buku penerimaan ke kantor pada jam Vina menimba air di sumur. Ia tidak sempat membuat salinan. Karsa menawarkan membantu membaca rak pada malam hari, lalu Vina menolak karena takut mereka tertangkap. Kehilangan catatan memperjelas bahaya, tetapi ketakutan masih lebih kuat daripada tindakan mereka.'] },
      { chapterNumber: 46, title: 'Dua Rak Dihitung Diam', paragraphs: ['Vina dan Karsa menghitung dua rak dari luar pintu sebelum rapat desa. Mereka menemukan selisih satu karung, namun tidak dapat memastikan kapan hilangnya. Bu Ningsih mendengar cerita itu dan meminta mereka mulai menulis angka. Langkah kecil membangun saksi, tetapi belum memberi alasan warga menuntut pintu dibuka.'] },
      { chapterNumber: 47, title: 'Hujan Membasahi Lumbung', paragraphs: ['Hujan membocorkan atap lumbung dan membuat satu karung rusak. Vina serta Karsa memindahkannya ke rak tinggi tanpa mencatat kerusakan lain. Mereka saling percaya lebih dari sebelumnya, tetapi pengambilan benih tetap tidak terlihat. Masalah baru memberi alasan berada di gudang, tanpa menyelesaikan siapa yang menguasai kuncinya.'] },
      { chapterNumber: 48, title: 'Lilin Masih Tersimpan', paragraphs: ['Vina menunjukkan lilin bekas kepada Danu dan menjelaskan rencana kunci kedua. Danu tidak melarang, tetapi meminta ia jangan bertindak sendiri. Ia belum menawarkan bantuan karena pekerjaannya rapuh. Percakapan membuat keluarga sedikit lebih jujur, namun salinan kunci dan aturan penjaga belum terwujud.'] },
      { chapterNumber: 49, title: 'Karsa Menunggu Jawaban', paragraphs: ['Karsa menunggu Vina di bengkelnya dengan alat kecil untuk membuat cetakan, tetapi Vina tidak membawa bentuk kunci. Mereka membicarakan kemungkinan kotak bersama lalu membiarkannya menjadi rencana. Pintu lumbung tetap terkunci oleh Bagas. Harapan terhadap cara baru hadir, tanpa perlindungan nyata bagi benih sebelum pembagian pagi.'] },
      { chapterNumber: 50, title: 'Simpul Disimpan di Kaleng', paragraphs: ['Pada akhir musim, Vina menyimpan potongan benang merah dan lilin dalam kaleng teh. Karsa berjanji membantu bila mereka memperoleh bentuk kunci. Satu karung masih hilang, dan warga belum tahu siapa menerima benihnya. Cerita memberi alat serta sekutu awal, tetapi lumbung belum berubah menjadi tempat yang diawasi bersama.'] },
    ], justification: 'Evidence fragments and an ally suggest future shared custody, but the ending leaves storehouse control and the missing sacks unresolved.' },
    { chapters: [
      { chapterNumber: 41, title: 'Peta Dibuka di Teras', paragraphs: ['Mbah Ripto membuka peta parit lama di teras saat Vina mengeluh gerbang atas ditutup. Ia menunjuk pintu kayu yang dahulu mengaliri teras bawah. Vina mendengarkan, tetapi tidak mengajak warga mencari jalur itu karena takut didenda. Peta memberi kemungkinan nyata, namun masih tinggal sebagai pengetahuan antara dua orang.'] },
      { chapterNumber: 42, title: 'Batu Putih Ditemukan', paragraphs: ['Vina menemukan satu batu putih dekat semak belakang kebun kopi dan membersihkan lumpurnya. Mbah Ripto berkata batu itu menandai belokan lama. Mereka belum mengukur arah berikutnya atau membawa saksi. Penemuan tersebut memberi bukti kecil bahwa peta tidak sepenuhnya bohong, namun belum cukup membuka jalan air.'] },
      { chapterNumber: 43, title: 'Bagas Memasang Larangan', paragraphs: ['Bagas memasang papan larangan di dekat semak dan berkata jalur lama milik kantor. Vina tidak membantah, tetapi menyimpan daun dengan gambar arah batu. Mbah Ripto melihatnya lalu mengangguk. Ketakutan mereka belum pecah, namun peta serta penanda mulai membentuk rahasia yang dapat dipakai suatu hari nanti.'] },
      { chapterNumber: 44, title: 'Dua Anak Membawa Kapur', paragraphs: ['Dua anak membantu Vina memberi garis kapur pada batu putih setelah pulang sekolah. Mereka tidak tahu mengapa tanda itu penting, dan Vina belum menjelaskan pada orang tua mereka. Kegiatan kecil memberi jalur lama sedikit perhatian, tetapi tidak menghubungkan penanda tersebut pada kebutuhan air semua warga.'] },
      { chapterNumber: 45, title: 'Ripto Melukai Lutut', paragraphs: ['Mbah Ripto terpeleset ketika menunjuk semak berikutnya dan lututnya bengkak. Vina membawanya pulang, lalu menyalahkan diri karena mengajak lelaki tua itu keluar. Ia tidak meneruskan pencarian atau meminta bantuan lain. Luka Mbah membuat jalur lama terasa lebih jauh, meski peta masih terbuka di meja.'] },
      { chapterNumber: 46, title: 'Peta Dilihat Bu Ningsih', paragraphs: ['Bu Ningsih datang membawa obat untuk Mbah Ripto dan melihat peta parit di meja. Vina menunjukkan batu putih serta garis kapur yang dibuat anak-anak. Guru itu berkata jalur tersebut perlu diperiksa bersama setelah lutut Mbah membaik. Kini ada satu saksi baru, tetapi belum ada warga yang berani menghadapi larangan Bagas.'] },
      { chapterNumber: 47, title: 'Hujan Membersihkan Semak', paragraphs: ['Hujan deras merobohkan sebagian semak dekat batu putih dan membuat arah parit lebih terlihat. Vina mengamati dari jauh sambil membawa obat untuk Mbah. Ia tidak memanggil warga karena jalan licin. Alam membuka sedikit jalan, namun keputusan untuk memakai jalur lama tetap tertunda.'] },
      { chapterNumber: 48, title: 'Mbah Menerima Tongkat', paragraphs: ['Karsa mengirim tongkat bambu bagi Mbah Ripto, dan Vina menyerahkannya di teras. Mbah berkata ia ingin melihat batu putih lagi saat kakinya kuat. Vina tidak menjanjikan apa pun, tetapi duduk mendengarkan kisah jalur air lama sampai senja. Hubungan mereka menghangat, tanpa mengubah gerbang atas yang masih tertutup.'] },
      { chapterNumber: 49, title: 'Garis Kapur Memudar', paragraphs: ['Coretan kapur di permukaan batu putih mulai memudar terkena hujan, sementara anak-anak menanyakan kapan mereka dapat menandai batu lain. Vina mengatakan mungkin setelah panen. Bu Ningsih menyimpan peta di kelas agar tidak rusak. Persiapan bertahan, tetapi jalur lama belum menjadi keputusan warga atau sumber air bagi teras bawah.'] },
      { chapterNumber: 50, title: 'Peta Menunggu Musim Baru', paragraphs: ['Pada akhir musim, Vina menaruh peta parit dalam tabung bambu dan menyimpannya di rumah jaga. Mbah Ripto masih memakai tongkat, sedangkan Bagas menjaga gerbang atas. Vina serta Bu Ningsih sepakat memanggil warga setelah panen. Cerita memberi jalan yang mungkin, tetapi air dan kuasa kantor belum benar-benar berubah.'] },
    ], justification: 'The old canal gains tangible markers, a new ally, and emotional care for Mbah Ripto, yet the water route remains an unrealized next-season possibility.' },
  ],
}
